INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_ADJECTIVE','Boundless');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_ANY','Any');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_ASSIGN','Assign');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_AUTO','Automatic');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_AUTOMATONS','Native automatons: {1_Num}. These are separate from population; remote credits are suspended.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_BALANCED','Balanced');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_BONUS','Registry territorial Culture');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_BONUS_HELP','Automatically maintained by The Grand Registry.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CAPACITY','Remote citizens use forced native labourers or a governor-proof surplus. Available citizens and additional safe remote capacity differ. Pending requests wait for capacity. Specialists remain native. See the guide for remaining engine restrictions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CAPITAL','The Heart of the World');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CIV','The Boundless City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CIV_PEDIA','There shall be no second city. For the first shall have no end.[NEWLINE][NEWLINE]The Boundless City measures civilization in streets, bridges and the citizens who walk them. Every new frontier becomes another district of the same capital. Its one production queue and one population remain the price of that ambition.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CULTURE','Culture');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DAWN','There shall be no second city. For the first shall have no end.[NEWLINE][NEWLINE]First Architect, the foundations are laid. Grow the Heart of the World, send your Surveyors beyond the familiar streets, and let every bridge join another district to your one great city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DEMOLISH','Demolish');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DEMOLISHED','A besieged settlement was demolished through its current owner’s native legal operation. No city or territory was acquired.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DIRECTION','Direction');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DISABLED','The saved Boundless state is invalid or newer than this mod. Remote yields have been removed. Consult Lua.log before continuing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DISTANCE','Distance');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_EAST','East');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_EXTRA_REMOVED','An unexpected additional settlement was removed after native razing checks allowed it. Its acquired plots were released; no additional city was retained.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_FAITH','Faith');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_FOOD','Food');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_GOLD','Gold');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_HYBRID','Hybrid');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_IMPROVEMENT','Improvement');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LEADER','The First Architect');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LEADER_PEDIA','The First Architect is an original fictional master builder. Their vision unites settlement, coast and distant island within one continuously growing city. Infrastructure and patient defense matter more than occupation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LOCATE','Locate');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LOCK','Lock');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_MANUAL','Manual');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_NEXT','Next');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_NORTH','North');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_NO_CAPTURE','One City, One Heart');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_NO_CAPTURE_HELP','Cannot capture enemy cities. The Boundless City cannot safely occupy foreign capitals or additional cities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_PENDING','Pending');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_PREVIOUS','Previous');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_PRODUCTION','Production');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_QUARANTINE','An unexpected additional city has no safe recipient. Its queues are cleared and resistance suppresses ordinary yields and purchases. See Lua.log and the limitations guide; no protected city was destroyed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_RECOVERY','An additional city was returned to an eligible owner. The Heart remains your only city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_RECOVERY_PENDING','Remote-work recovery is pending. New capacity is unavailable until the native ledger can be verified. Check Lua.log; an unverified source may still require cleanup.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_REGISTRY','The Grand Registry');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_REGISTRY_HELP','+3 Culture. +1 additional Culture per 10 owned plots, capped at +10. Reduces the separate frontier Culture cost by 15%. Retains the active Monument rules.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_REGISTRY_PEDIA','The Grand Registry records each district as part of the same city, whether it lies beside the heart or across a distant sea. The territorial Culture bonus is counted once and never exceeds ten.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_REGISTRY_STRATEGY','Build early to drive frontier growth and support ordinary Social Policies.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_RELEASE','Release');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_RESOURCE','Resource');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SCIENCE','Science');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SHORT','The Boundless City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE','Siege demolition');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_DAMAGE','Insufficient damage. Reduce the city to 1 HP.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_ENGINE_LIMIT','Native interface rejects the current owner’s own-founded city; demolition is unavailable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_HELP','Only adjacent melee forces with moves remaining can demolish a city at 1 HP, at war, when its current owner can legally raze it. Original capitals, holy cities and city-states are excluded. Normal first-founded settlements usually fail this native check.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_INACTIVE','The original capital and an active player turn are required.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_INVALID','No eligible foreign settlement exists here.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_KNOWN_CITY','Previously revealed settlement');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_MELEE','No adjacent non-embarked melee unit with movement remaining.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_NATIVE_RULE','Native razing rules or another mod prohibit demolition.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_NOT_AT_WAR','Not at war with this settlement’s owner.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_NOT_VISIBLE','Not currently visible. Reveal the city to check its present condition.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_PROTECTED','Protected capital, holy city, city-state settlement or city already razing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_QUEUED','Demolition is already queued for deferred revalidation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SIEGE_READY','Ready for native-legal demolition.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SOUTH','South');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_1','Registry Envoy 1');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_10','Registry Envoy 10');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_2','Registry Envoy 2');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_3','Registry Envoy 3');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_4','Registry Envoy 4');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_5','Registry Envoy 5');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_6','Registry Envoy 6');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_7','Registry Envoy 7');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_8','Registry Envoy 8');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_9','Registry Envoy 9');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_STRATEGY','Grow your capital, build The Grand Registry, and use Surveyors to develop the frontier. Choose remote tiles in The Boundless Workforce. Science, Culture and Diplomatic victories use normal rules; foreign capitals cannot be occupied for Domination.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SUMMARY','Population: {1_Num} | Owned plots: {2_Num}[NEWLINE]Local: {3_Num} | Remote: {4_Num} | Specialists: {5_Num} | Idle labourers: {6_Num} | Unassigned: {7_Num}[NEWLINE]Available citizens: {8_Num} | Additional remote capacity: {9_Num} | Remote limit: {10_Num}[NEWLINE]Pending requests: {11_Num} | Locked requests: {12_Num}[NEWLINE]Frontier Culture: {13_Num} / {14_Num}');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SURVEYOR','Frontier Surveyor');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SURVEYOR_HELP','Replaces Worker. 3 Movement and 125% of the ordinary Worker base work rate. Completing an improvement on an owned plot more than five hexes from the capital grants 5 Culture once per plot per Boundless player. Repairs and routes do not qualify.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SURVEYOR_PEDIA','The Frontier Surveyor treats the horizon as another street waiting to be drawn. Surveyors retain the active Worker build permissions, automation roles and upgrade relationships.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SURVEYOR_STRATEGY','Develop strong frontier tiles. Distant work still requires citizen reservations; territory alone produces no additional tile yields.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_TRAIT','The World Is One City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_TRAIT_HELP','Keep your original capital. Culture funds contiguous frontier expansion without a distance limit. Assign real citizens to distant owned tiles using forced labourers and verified surplus labourers. Military units cannot capture cities; restricted siege demolition requires native legal razing checks. See the civilization guide for remaining capacity and transfer limits.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_UNAVAILABLE','This command is unavailable or the plot cannot be reserved.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_UNLOCK','Unlock');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_WEST','West');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_WORKFORCE','The Boundless Workforce');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_WORKFORCE_VIEW','Remote districts');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_YIELD','Yield');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_YIELDS','Gross remote plot yields: {1_String}[NEWLINE]Labourer yields removed: {2_String}[NEWLINE]Net base contribution: {3_String}');
